import{_ as r,o as e,c as d,a5 as a}from"./chunks/framework.BF53ZjCA.js";const f=JSON.parse('{"title":"颜色成因","description":"","frontmatter":{"title":"颜色成因"},"headers":[],"relativePath":"zh/classification/color-causes/intro.md","filePath":"zh/classification/color-causes/intro.md","lastUpdated":1790876393000}'),o={name:"zh/classification/color-causes/intro.md"};function l(s,t,n,i,h,c){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="颜色成因" tabindex="-1">颜色成因 <a class="header-anchor" href="#颜色成因" aria-label="Permalink to &quot;颜色成因&quot;">​</a></h1><p>颜色不是孤立的外观标签，而是光与物质相互作用后的结果。本分类模块从吸收型体色与结构型光学色两条路径，进入三种常见的致色机制：</p><h2 id="先分清两条路径" tabindex="-1">先分清两条路径 <a class="header-anchor" href="#先分清两条路径" aria-label="Permalink to &quot;先分清两条路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>光与物质的关系</th><th>典型结果</th></tr></thead><tbody><tr><td>吸收型体色</td><td>宝石选择性吸收部分可见光，剩余光线进入眼睛</td><td>红宝石、祖母绿、蓝宝石的体色</td></tr><tr><td>结构型光学色</td><td>微结构使光发生散射、干涉或衍射，颜色随角度或光源改变</td><td>欧泊变彩、月光石月光效应、拉长石晕彩</td></tr></tbody></table><h2 id="三种主要机制" tabindex="-1">三种主要机制 <a class="header-anchor" href="#三种主要机制" aria-label="Permalink to &quot;三种主要机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>机制</th><th>概述</th></tr></thead><tbody><tr><td><a href="./transition-metal.html">过渡金属离子致色</a></td><td>过渡金属离子（如 Cr、Fe、Mn、Co、Ni、V、Cu、Ti）含有未填满的 d</td></tr><tr><td>或 f 电子层。当这些离子进入晶格取代主晶格中的位置（如 Al、Si、</td><td></td></tr><tr><td>Mg）时，其能级被晶场劈裂为多组 d-d 跃迁。吸收可见光特定波段后，</td><td></td></tr><tr><td>透射或反射光中残留的颜色即为我们看到的颜色。这是宝石界最重要</td><td></td></tr><tr><td>的致色机制，在许多常见有色宝石中都很重要。</td><td></td></tr><tr><td></td><td></td></tr><tr><td><a href="./color-centers.html">色心致色</a></td><td>色心是晶格中能选择性吸收可见光的点缺陷。当晶格缺少某个离子</td></tr><tr><td>（空位）、多出一个离子（间隙），或含有杂质离子改变局部电荷平衡</td><td></td></tr><tr><td>时，邻近的电子或空穴被束缚在缺陷处形成&quot;色心&quot;，其能级刚好落在</td><td></td></tr><tr><td>可见光波段。色心可通过天然辐射或人工辐照（如加热后辐照）产生，</td><td></td></tr><tr><td>也可能因日晒褪色，这是检测优化处理的关键判断点。</td><td></td></tr><tr><td></td><td></td></tr><tr><td><a href="./charge-transfer.html">电荷转移</a></td><td>电荷转移是电子在相邻离子或同一离子的不同能级之间跳跃吸收光子</td></tr><tr><td>的过程。与 d-d 跃迁相比，电荷转移的吸收强度通常高 10²–10⁴ 倍，</td><td></td></tr><tr><td>因此即使致色离子浓度很低也能产生饱和浓艳的颜色。常见类型：</td><td></td></tr><tr><td><strong>金属-金属电荷转移（MMCT）</strong>、<strong>氧-金属电荷转移（OMCT）</strong>、</td><td></td></tr><tr><td><strong>金属-配体电荷转移（MLCT）</strong>。</td><td></td></tr><tr><td></td><td></td></tr></tbody></table><p>颜色分类适合帮助观察和检索，但不能替代鉴定。同一种颜色可能来自不同机制；进入具体机制时，还应结合色相、明度、饱和度、光源和观察方向。</p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gems-gemology" target="_blank" rel="noreferrer">GIA：宝石与颜色研究</a><span>宝石颜色、光学表现与宝石学研究背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA：现象宝石的结构</a><span>结构型光学色与微结构观察线索</span><small>打开来源 ↗</small></li></ul></aside><p><em>参见<a href="./../intro.html">分类总览</a>了解矿物分类框架。</em></p>',9)])])}const p=r(o,[["render",l]]);export{f as __pageData,p as default};
